int engine_midi_held(void)   /* host test: bit k the 303 k gate, bit 8 + s the break slice key s */
{
    int k, r = brk.keys << 8 & 0xFF00;
    for (k = 0; k < NBASS; k++)
#if X0X_DEV_WOBBLE
        r |= synth_active(&bass_slot[k]) ? 1 << k : 0;
#else
        r |= b303[k].gate ? 1 << k : 0;
#endif
    return r;
}
